		},
		mark: true,
		filter(event, player) {
			if (event.type !== "dying") {
				return false;
			}
			if (player.storage.shouyin) {
				return false;
			}
			if (player.isTurnedOver()) {
				return false;
			}
			return true;
		},
		content() {
			"step 0";
			player.awakenSkill(event.name);
			player.storage.shouyin = true;
			player.turnOver();
			"step 1";
			event.targets = game.filterPlayer();
			event.targets.sort(lib.sort.seat);
			"step 2";
			if (event.targets.length) {
				var target = event.targets.shift();
				if (target.hp < target.maxHp) {
					var num = target.maxHp - target.hp;
					target.recover(num);
					player.line(target, "green");
				}
				event.redo();
			}
		},
		ai: {
			skillTagFilter(player) {
				if (player.storage.shouyin) {
					return false;
				}
			},
			expose: 0.3,
			save: true,
			result: {
				player(player) {
					if (_status.event.dying !== player && get.attitude(player, _status.event.dying) <= 0) {
						return 0;
					}
					var num = 0;
					var players = game.filterPlayer();
					for (var i = 0; i < players.length; i++) {
						var del = players[i].maxHp - players[i].hp;
						del /= Math.pow(1 + players[i].hp, 0.2);
						num += get.sgnAttitude(player, players[i]) * del;
					}
					return num;
				},
			},
		},
		intro: {
			content: "limited",
		},
	}

